import { getAccountDb } from '../account-db.js';

// [eb] Idempotent migration for audit_log table.
// Called once at server startup, before routes are registered.
export function runAuditMigrations(): void {
  const db = getAccountDb();
  db.mutate(`
    CREATE TABLE IF NOT EXISTS audit_log (
      id         INTEGER PRIMARY KEY AUTOINCREMENT,
      timestamp  INTEGER NOT NULL DEFAULT (strftime('%s', 'now')),
      event_type TEXT    NOT NULL,
      actor      TEXT    NOT NULL,
      ip_address TEXT,
      outcome    TEXT    NOT NULL CHECK(outcome IN ('success', 'fail')),
      details    TEXT
    )
  `);
  db.mutate(
    'CREATE INDEX IF NOT EXISTS idx_audit_log_event ON audit_log (event_type, timestamp)',
  );
}

import { createHash } from 'node:crypto';

import { getAccountDb } from '../account-db.js';
import logger from './logger.js';

export type AuditEventType =
  | 'login_success'
  | 'login_failure'
  | 'bootstrap'
  | 'password_change'
  | 'openid_auth'
  | 'eb_consent_auth'
  | 'eb_consent_expiry'
  | 'eb_consent_renewal'
  | 'eb_account_link';

function hashActor(token: string): string {
  return createHash('sha256').update(token).digest('hex').slice(0, 8);
}

export function writeAuditLog(opts: {
  event_type: AuditEventType;
  actor: string;
  ip_address?: string;
  outcome: 'success' | 'fail';
  details?: Record<string, unknown>;
}): void {
  try {
    const db = getAccountDb();
    const actorValue =
      opts.actor === 'system' ? 'system' : hashActor(opts.actor);
    db.mutate(
      `INSERT INTO audit_log (event_type, actor, ip_address, outcome, details)
       VALUES (?, ?, ?, ?, ?)`,
      [
        opts.event_type,
        actorValue,
        opts.ip_address ?? null,
        opts.outcome,
        opts.details ? JSON.stringify(opts.details) : null,
      ],
    );
  } catch (err) {
    logger.error('audit log write failed', {
      error: String(err),
      event_type: opts.event_type,
    });
  }
}

