const MAX_SAMPLES = 1000;
const latencySamples: number[] = [];

export function recordLatency(ms: number): void {
  if (latencySamples.length >= MAX_SAMPLES) latencySamples.shift();
  latencySamples.push(ms);
}

export function getLatencyPercentiles(): {
  p50: number;
  p95: number;
  p99: number;
} | null {
  if (latencySamples.length === 0) return null;
  const sorted = [...latencySamples].sort((a, b) => a - b);
  const p = (pct: number) =>
    sorted[Math.floor((sorted.length * pct) / 100)] ?? sorted[sorted.length - 1];
  return { p50: p(50), p95: p(95), p99: p(99) };
}

const syncStats = {
  totalRuns: 0,
  successRuns: 0,
  failedRuns: 0,
  lastRunAt: null as number | null,
  lastRunAccounts: 0,
  lastRunErrors: 0,
};

export function recordSyncRun(accounts: number, errors: number): void {
  syncStats.totalRuns++;
  if (errors === 0) syncStats.successRuns++;
  else syncStats.failedRuns++;
  syncStats.lastRunAt = Date.now();
  syncStats.lastRunAccounts = accounts;
  syncStats.lastRunErrors = errors;
}

export function getSyncStats() {
  return { ...syncStats };
}

// For testing: reset all module-level state
export function _resetMetrics(): void {
  latencySamples.length = 0;
  syncStats.totalRuns = 0;
  syncStats.successRuns = 0;
  syncStats.failedRuns = 0;
  syncStats.lastRunAt = null;
  syncStats.lastRunAccounts = 0;
  syncStats.lastRunErrors = 0;
}

import logger from './logger.js';

type Severity = 'info' | 'warning' | 'error';

export type StoredAlert = {
  id: string;
  event_type: string;
  message: string;
  timestamp: string;
  severity: Severity;
};

const cooldowns = new Map<string, number>();
const COOLDOWN_MS = 60 * 60 * 1000; // 1 hour
const MAX_ALERTS = 50;
const recentAlerts: StoredAlert[] = [];
let alertCounter = 0;

export async function triggerAlert(opts: {
  event_type: string;
  message: string;
  severity: Severity;
}): Promise<void> {
  const lastFired = cooldowns.get(opts.event_type) ?? 0;
  if (Date.now() - lastFired < COOLDOWN_MS) return;
  cooldowns.set(opts.event_type, Date.now());

  const timestamp = new Date().toISOString();

  // Always store in-memory for client polling (even without webhook configured)
  const alert: StoredAlert = {
    id: `alert-${++alertCounter}`,
    event_type: opts.event_type,
    message: opts.message,
    timestamp,
    severity: opts.severity,
  };
  if (recentAlerts.length >= MAX_ALERTS) recentAlerts.shift();
  recentAlerts.push(alert);

  // Webhook delivery is optional and fire-and-forget
  const webhookUrl = process.env.ALERT_WEBHOOK_URL;
  if (!webhookUrl) return;

  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 5000);
  try {
    await fetch(webhookUrl, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        event_type: opts.event_type,
        message: opts.message,
        timestamp,
        severity: opts.severity,
      }),
      signal: controller.signal,
    });
  } catch (err) {
    logger.warn('webhook alert failed', {
      event_type: opts.event_type,
      error: String(err),
    });
  } finally {
    clearTimeout(timeout);
  }
}

/** Returns all unacknowledged alerts (oldest first). */
export function getRecentAlerts(): StoredAlert[] {
  return [...recentAlerts];
}

/** Remove an alert by id (user acknowledged it). Returns true if found. */
export function acknowledgeAlert(alertId: string): boolean {
  const idx = recentAlerts.findIndex(a => a.id === alertId);
  if (idx === -1) return false;
  recentAlerts.splice(idx, 1);
  return true;
}

// For testing: reset all module-level state
export function _resetAlerter(): void {
  cooldowns.clear();
  recentAlerts.length = 0;
  alertCounter = 0;
}

import { describe, it, expect, beforeEach } from 'vitest';

import {
  recordLatency,
  getLatencyPercentiles,
  recordSyncRun,
  getSyncStats,
  _resetMetrics,
} from './metrics.js';

describe('metrics collector', () => {
  beforeEach(() => {
    _resetMetrics();
  });

  describe('getLatencyPercentiles', () => {
    it('returns null when no samples have been recorded', () => {
      expect(getLatencyPercentiles()).toBeNull();
    });

    it('returns p50/p95/p99 after recording samples', () => {
      // Record 100 samples: 1ms through 100ms
      for (let i = 1; i <= 100; i++) {
        recordLatency(i);
      }
      const result = getLatencyPercentiles();
      expect(result).not.toBeNull();
      expect(result).toHaveProperty('p50');
      expect(result).toHaveProperty('p95');
      expect(result).toHaveProperty('p99');
      // p50 should be around the median
      expect(result!.p50).toBeGreaterThanOrEqual(49);
      expect(result!.p50).toBeLessThanOrEqual(51);
      // p99 should be near the top
      expect(result!.p99).toBeGreaterThanOrEqual(98);
    });
  });

  describe('fixed-size eviction', () => {
    it('never exceeds MAX_SAMPLES (1000) and evicts oldest', () => {
      // Record 1100 samples
      for (let i = 1; i <= 1100; i++) {
        recordLatency(i);
      }
      const result = getLatencyPercentiles();
      expect(result).not.toBeNull();
      // p50 of samples 101-1100 (sorted) should be around 600, not around 50
      expect(result!.p50).toBeGreaterThanOrEqual(550);
    });
  });

  describe('recordSyncRun', () => {
    it('increments totalRuns and tracks success/failure counts', () => {
      recordSyncRun(5, 0); // success
      recordSyncRun(3, 1); // failure
      recordSyncRun(2, 0); // success

      const stats = getSyncStats();
      expect(stats.totalRuns).toBe(3);
      expect(stats.successRuns).toBe(2);
      expect(stats.failedRuns).toBe(1);
    });

    it('getSyncStats returns correct lastRunAt timestamp and lastRunAccounts', () => {
      const before = Date.now();
      recordSyncRun(7, 0);
      const after = Date.now();

      const stats = getSyncStats();
      expect(stats.lastRunAt).toBeGreaterThanOrEqual(before);
      expect(stats.lastRunAt).toBeLessThanOrEqual(after);
      expect(stats.lastRunAccounts).toBe(7);
      expect(stats.lastRunErrors).toBe(0);
    });
  });
});

import { describe, it, expect, vi, beforeEach } from 'vitest';

// Mock logger to suppress output during tests
vi.mock('./logger.js', () => ({
  default: {
    error: vi.fn(),
    warn: vi.fn(),
    info: vi.fn(),
  },
}));

import {
  triggerAlert,
  getRecentAlerts,
  acknowledgeAlert,
  _resetAlerter,
} from './alerter.js';

describe('alerter', () => {
  beforeEach(() => {
    _resetAlerter();
    vi.unstubAllEnvs();
    vi.stubGlobal('fetch', vi.fn().mockResolvedValue({ ok: true }));
  });

  it('sends POST to ALERT_WEBHOOK_URL with correct JSON payload shape', async () => {
    vi.stubEnv('ALERT_WEBHOOK_URL', 'https://hooks.example.com/alert');
    await triggerAlert({
      event_type: 'sync_failure',
      message: 'Sync failed for account X',
      severity: 'error',
    });

    expect(fetch).toHaveBeenCalledOnce();
    const [url, options] = (fetch as ReturnType<typeof vi.fn>).mock.calls[0] as [
      string,
      RequestInit,
    ];
    expect(url).toBe('https://hooks.example.com/alert');
    expect(options.method).toBe('POST');
    const body = JSON.parse(options.body as string);
    expect(body).toHaveProperty('event_type', 'sync_failure');
    expect(body).toHaveProperty('message', 'Sync failed for account X');
    expect(body).toHaveProperty('severity', 'error');
    expect(body).toHaveProperty('timestamp');
  });

  it('does nothing (no fetch) when ALERT_WEBHOOK_URL is not set, but still stores alert in-memory', async () => {
    // Do not stub ALERT_WEBHOOK_URL - leave unset
    await triggerAlert({
      event_type: 'sync_failure',
      message: 'no webhook',
      severity: 'warning',
    });

    expect(fetch).not.toHaveBeenCalled();
    const alerts = getRecentAlerts();
    expect(alerts).toHaveLength(1);
    expect(alerts[0].event_type).toBe('sync_failure');
  });

  it('respects 1-hour cooldown per event_type (second call within 1h is suppressed)', async () => {
    vi.stubEnv('ALERT_WEBHOOK_URL', 'https://hooks.example.com/alert');
    await triggerAlert({ event_type: 'quota_exceeded', message: 'first', severity: 'warning' });
    await triggerAlert({ event_type: 'quota_exceeded', message: 'second', severity: 'warning' });

    // Only one fetch and one alert stored
    expect(fetch).toHaveBeenCalledTimes(1);
    expect(getRecentAlerts()).toHaveLength(1);
  });

  it('does not throw when fetch fails (logs warning instead)', async () => {
    vi.stubEnv('ALERT_WEBHOOK_URL', 'https://hooks.example.com/alert');
    vi.stubGlobal('fetch', vi.fn().mockRejectedValue(new Error('network error')));

    await expect(
      triggerAlert({ event_type: 'test_failure', message: 'oops', severity: 'error' }),
    ).resolves.toBeUndefined();
  });

  it('stores alert in recentAlerts; getRecentAlerts returns it with correct shape', async () => {
    await triggerAlert({ event_type: 'consent_expiry', message: 'expiring soon', severity: 'info' });

    const alerts = getRecentAlerts();
    expect(alerts).toHaveLength(1);
    const alert = alerts[0];
    expect(alert).toHaveProperty('id');
    expect(alert).toHaveProperty('event_type', 'consent_expiry');
    expect(alert).toHaveProperty('message', 'expiring soon');
    expect(alert).toHaveProperty('severity', 'info');
    expect(alert).toHaveProperty('timestamp');
  });

  it('acknowledgeAlert removes alert by id; getRecentAlerts no longer returns it', async () => {
    await triggerAlert({ event_type: 'consent_expiry', message: 'expiring', severity: 'info' });
    const [alert] = getRecentAlerts();
    expect(alert).toBeDefined();

    const result = acknowledgeAlert(alert.id);
    expect(result).toBe(true);
    expect(getRecentAlerts()).toHaveLength(0);
  });

  it('acknowledgeAlert returns false for unknown id', () => {
    expect(acknowledgeAlert('alert-nonexistent')).toBe(false);
  });

  it('evicts oldest alert when recentAlerts exceeds MAX_ALERTS (50)', async () => {
    // Trigger 51 alerts each with a unique event_type to bypass cooldown
    for (let i = 0; i < 51; i++) {
      await triggerAlert({
        event_type: `unique_event_${i}`,
        message: `alert ${i}`,
        severity: 'info',
      });
    }

    const alerts = getRecentAlerts();
    expect(alerts).toHaveLength(50);
    // The first alert (unique_event_0) should have been evicted
    expect(alerts.find(a => a.event_type === 'unique_event_0')).toBeUndefined();
    // The last alert should still be present
    expect(alerts.find(a => a.event_type === 'unique_event_50')).toBeDefined();
  });
});

