106→        const packageJsonPath = resolve(currentPath, 'package.json');
107→        if (fs.existsSync(packageJsonPath)) {
108→          const packageJson = JSON.parse(
109→            readFileSync(packageJsonPath, 'utf-8'),
110→          );
111→
112→          if (packageJson.name === '@actual-app/sync-server') {
113→            return packageJson;
114→          }
115→        }
116→
117→        currentPath = resolve(join(currentPath, '..')); // Move up one directory
118→        directoriesSearched++;
119→      }
120→    } catch (error) {
121→      console.error('Error while searching for package.json:', error);
122→    }
123→
124→    return null;
125→  }
126→
127→  const dirname = resolve(fileURLToPath(import.meta.url), '../');
128→  const packageJson = findPackageJson(dirname);
129→
130→  res.status(200).json({
131→    build: {
132→      name: packageJson?.name,
133→      description: packageJson?.description,
134→      version: packageJson?.version,
135→    },
136→  });
137→});
