 12→export async function pollGoCardlessWebToken({
 13→  requisitionId,
 14→}: {
 15→  requisitionId: string;
 16→}) {
 17→  const userToken = await asyncStorage.getItem('user-token');
 18→  if (!userToken) return { error: 'unknown' };
 19→
 20→  const startTime = Date.now();
 21→  stopPolling = false;
 22→
 23→  async function getData(
 24→    cb: (
 25→      data:
 26→        | { status: 'timeout' }
 27→        | { status: 'unknown'; message?: string }
 28→        | { status: 'success'; data: GoCardlessToken },
 29→    ) => void,
 30→  ) {
 31→    if (stopPolling) {
 32→      return;
 33→    }
 34→
 35→    if (Date.now() - startTime >= 1000 * 60 * 10) {
 36→      cb({ status: 'timeout' });
 37→      return;
 38→    }
 39→
 40→    const serverConfig = getServer();
 41→    if (!serverConfig) {
 42→      throw new Error('Failed to get server config.');
 43→    }
 44→
 45→    const data = await post(
 46→      serverConfig.GOCARDLESS_SERVER + '/get-accounts',
 47→      {
 48→        requisitionId,
 49→      },
 50→      {
 51→        'X-ACTUAL-TOKEN': userToken,
 52→      },
 53→    );
 54→
 55→    if (data) {
 56→      if (data.error_code) {
 57→        logger.error('Failed linking gocardless account:', data);
 58→        cb({ status: 'unknown', message: data.error_type });
 59→      } else {
 60→        cb({ status: 'success', data });
 61→      }
 62→    } else {
 63→      setTimeout(() => getData(cb), 3000);
 64→    }
 65→  }
 66→
 67→  return new Promise(resolve => {
 68→    getData(data => {
 69→      if (data.status === 'success') {
 70→        resolve({ data: data.data });
 71→        return;
 72→      }
 73→
 74→      if (data.status === 'timeout') {
 75→        resolve({ error: data.status });
 76→        return;
 77→      }
 78→
 79→      resolve({
 80→        error: data.status,
 81→        message: data.message,
 82→      });
 83→    });
 84→  });
 85→}
