206→async function closeAccount({
207→  id,
208→  transferAccountId,
209→  categoryId,
210→  forced = false,
211→}: {
212→  id: AccountEntity['id'];
213→  transferAccountId?: AccountEntity['id'] | undefined;
214→  categoryId?: CategoryEntity['id'] | undefined;
215→  forced?: boolean | undefined;
216→}) {
217→  await unlinkAccount({ id });
218→
219→  return withUndo(async () => {
220→    const account = await db.first<db.DbAccount>(
221→      'SELECT * FROM accounts WHERE id = ? AND tombstone = 0',
222→      [id],
223→    );
224→
225→    if (!account || account.closed === 1) {
226→      return;
227→    }
228→
229→    const { balance, numTransactions } = await getAccountProperties({ id });
230→
231→    if (numTransactions === 0) {
232→      await db.deleteAccount({ id });
233→    } else if (forced) {
234→      const rows = await db.runQuery<
235→        Pick<db.DbViewTransaction, 'id' | 'transfer_id'>
236→      >(
237→        'SELECT id, transfer_id FROM v_transactions WHERE account = ?',
238→        [id],
239→        true,
240→      );
241→
242→      const transferPayee = await db.first<Pick<db.DbPayee, 'id'>>(
243→        'SELECT id FROM payees WHERE transfer_acct = ?',
244→        [id],
245→      );
246→
247→      if (!transferPayee) {
248→        throw new Error(`Transfer payee with account ID ${id} not found.`);
249→      }
250→
251→      await batchMessages(async () => {
252→        rows.forEach(row => {
253→          if (row.transfer_id) {
254→            db.updateTransaction({
255→              id: row.transfer_id,
256→              payee: null,
257→              transfer_id: null,
258→            });
259→          }
260→
261→          db.deleteTransaction({ id: row.id });
262→        });
263→
264→        db.deleteAccount({ id });
265→        db.deleteTransferPayee({ id: transferPayee.id });
266→      });
267→    } else {
268→      if (balance !== 0 && transferAccountId == null) {
269→        throw APIError('balance is non-zero: transferAccountId is required');
270→      }
271→
272→      if (id === transferAccountId) {
273→        throw APIError('transfer account can not be the account being closed');
274→      }
275→
276→      await db.update('accounts', { id, closed: 1 });
277→
278→      if (balance !== 0 && transferAccountId) {
279→        const transferPayee = await db.first<Pick<db.DbPayee, 'id'>>(
280→          'SELECT id FROM payees WHERE transfer_acct = ?',
281→          [transferAccountId],
282→        );
283→
284→        if (!transferPayee) {
285→          throw new Error(
286→            `Transfer payee with account ID ${transferAccountId} not found.`,
287→          );
288→        }
289→
290→        await mainApp.handlers['transaction-add']({
291→          id: uuidv4(),
292→          payee: transferPayee.id,
293→          amount: -balance,
294→          account: id,
295→          date: monthUtils.currentDay(),
296→          notes: 'Closing account',
297→          category: categoryId,
298→        });
299→      }
300→    }
301→  });
302→}
