318→async function accountsBankSync({
319→  ids = [],
320→}: {
321→  ids: Array<AccountEntity['id']>;
322→}): Promise<SyncResponseWithErrors> {
323→  const { 'user-id': userId, 'user-key': userKey } =
324→    await asyncStorage.multiGet(['user-id', 'user-key']);
325→
326→  const accounts = await db.runQuery<
327→    db.DbAccount & { bankId: db.DbBank['bank_id'] }
328→  >(
329→    `
330→    SELECT a.*, b.bank_id as bankId
331→    FROM accounts a
332→    LEFT JOIN banks b ON a.bank = b.id
333→    WHERE a.tombstone = 0 AND a.closed = 0
334→      ${ids.length ? `AND a.id IN (${ids.map(() => '?').join(', ')})` : ''}
335→    ORDER BY a.offbudget, a.sort_order
336→  `,
337→    ids,
338→    true,
339→  );
340→
341→  const errors: ReturnType<typeof handleSyncError>[] = [];
342→  const newTransactions: Array<TransactionEntity['id']> = [];
343→  const matchedTransactions: Array<TransactionEntity['id']> = [];
344→  const updatedAccounts: Array<AccountEntity['id']> = [];
345→
346→  for (const acct of accounts) {
347→    if (acct.bankId && acct.account_id) {
348→      try {
349→        logger.group('Bank Sync operation for account:', acct.name);
350→        const syncResponse = await bankSync.syncAccount(
351→          userId as string,
352→          userKey as string,
353→          acct.id,
354→          acct.account_id,
355→          acct.bankId,
356→        );
357→
358→        const syncResponseData = await handleSyncResponse(syncResponse, acct);
359→
360→        newTransactions.push(...syncResponseData.newTransactions);
361→        matchedTransactions.push(...syncResponseData.matchedTransactions);
362→        updatedAccounts.push(...syncResponseData.updatedAccounts);
363→      } catch (err) {
364→        const error = err as Error;
365→        errors.push(handleSyncError(error, acct));
366→        captureException({
367→          ...error,
368→          message: 'Failed syncing account "' + acct.name + '."',
369→        } as Error);
370→      } finally {
371→        logger.groupEnd();
372→      }
373→    }
374→  }
375→
376→  if (updatedAccounts.length > 0) {
377→    connection.send('sync-event', {
378→      type: 'success',
379→      tables: ['transactions'],
380→    });
381→  }
382→
383→  return { errors, newTransactions, matchedTransactions, updatedAccounts };
384→}
