386→async function simpleFinBatchSync({
387→  ids = [],
388→}: {
389→  ids: Array<AccountEntity['id']>;
390→}): Promise<
391→  Array<{ accountId: AccountEntity['id']; res: SyncResponseWithErrors }>
392→> {
393→  const accounts = await db.runQuery<
394→    db.DbAccount & { bankId: db.DbBank['bank_id'] }
395→  >(
396→    `SELECT a.*, b.bank_id as bankId FROM accounts a
397→         LEFT JOIN banks b ON a.bank = b.id
398→         WHERE
399→          a.tombstone = 0
400→          AND a.closed = 0
401→          AND a.account_sync_source = 'simpleFin'
402→          ${ids.length ? `AND a.id IN (${ids.map(() => '?').join(', ')})` : ''}
403→         ORDER BY a.offbudget, a.sort_order`,
404→    ids.length ? ids : [],
405→    true,
406→  );
407→
408→  const retVal: Array<{
409→    accountId: AccountEntity['id'];
410→    res: {
411→      errors: ReturnType<typeof handleSyncError>[];
412→      newTransactions: Array<TransactionEntity['id']>;
413→      matchedTransactions: Array<TransactionEntity['id']>;
414→      updatedAccounts: Array<AccountEntity['id']>;
415→    };
416→  }> = [];
417→
418→  logger.group('Bank Sync operation for all SimpleFin accounts');
419→  try {
420→    const syncResponses: Array<{
421→      accountId: AccountEntity['id'];
422→      res: {
423→        error_code: string;
424→        error_type: string;
425→        added: Array<TransactionEntity['id']>;
426→        updated: Array<TransactionEntity['id']>;
427→      };
428→    }> = await bankSync.simpleFinBatchSync(
429→      accounts.map(a => ({
430→        id: a.id,
431→        account_id: a.account_id || null,
432→      })),
433→    );
434→    for (const syncResponse of syncResponses) {
435→      const account = accounts.find(a => a.id === syncResponse.accountId);
436→      if (!account) {
437→        logger.error(
438→          `Invalid account ID found in response: ${syncResponse.accountId}. Proceeding to the next account...`,
439→        );
440→        continue;
441→      }
442→
443→      const errors: ReturnType<typeof handleSyncError>[] = [];
444→      const newTransactions: Array<TransactionEntity['id']> = [];
445→      const matchedTransactions: Array<TransactionEntity['id']> = [];
446→      const updatedAccounts: Array<AccountEntity['id']> = [];
447→
448→      if (syncResponse.res.error_code) {
449→        errors.push(
450→          handleSyncError(
451→            {
452→              type: 'BankSyncError',
453→              reason: 'Failed syncing account "' + account.name + '."',
454→              category: syncResponse.res.error_type,
455→              code: syncResponse.res.error_code,
456→            } as BankSyncError,
457→            account,
458→          ),
459→        );
460→      } else {
461→        const syncResponseData = await handleSyncResponse(
462→          syncResponse.res,
463→          account,
464→        );
465→
466→        newTransactions.push(...syncResponseData.newTransactions);
467→        matchedTransactions.push(...syncResponseData.matchedTransactions);
468→        updatedAccounts.push(...syncResponseData.updatedAccounts);
469→      }
470→
471→      retVal.push({
472→        accountId: syncResponse.accountId,
473→        res: { errors, newTransactions, matchedTransactions, updatedAccounts },
474→      });
475→    }
476→  } catch (err) {
477→    const errors = [];
478→    for (const account of accounts) {
479→      retVal.push({
480→        accountId: account.id,
481→        res: {
482→          errors,
483→          newTransactions: [],
484→          matchedTransactions: [],
485→          updatedAccounts: [],
486→        },
487→      });
488→      const error = err as Error;
489→      errors.push(handleSyncError(error, account));
490→    }
491→  }
492→
493→  if (retVal.some(a => a.res.updatedAccounts.length > 0)) {
494→    connection.send('sync-event', {
495→      type: 'success',
496→      tables: ['transactions'],
497→    });
498→  }
499→
500→  logger.groupEnd();
501→
502→  return retVal;
503→}
