  8→function throwIfNot200(res: Response, text: string) {
  9→  if (res.status !== 200) {
 10→    if (res.status === 500) {
 11→      throw new PostError(res.status === 500 ? 'internal' : text);
 12→    }
 13→
 14→    const contentType = res.headers.get('Content-Type');
 15→    if (contentType.toLowerCase().indexOf('application/json') !== -1) {
 16→      const json = JSON.parse(text);
 17→      throw new PostError(json.reason);
 18→    }
 19→
 20→    // Actual Sync Server may be exposed via a tunnel (e.g. ngrok). Tunnel errors should be treated as network errors.
 21→    const tunnelErrorHeaders = ['ngrok-error-code'];
 22→    const tunnelError = tunnelErrorHeaders.some(header =>
 23→      res.headers.has(header),
 24→    );
 25→
 26→    if (tunnelError) {
 27→      // Tunnel errors are present when the tunnel is active and the server is not reachable e.g. server is offline
 28→      // When we experience a tunnel error we treat it as a network failure
 29→      throw new PostError('network-failure');
 30→    }
 31→
 32→    throw new PostError(text);
 33→  }
 34→}
