 1→const MAX_SAMPLES = 1000;
 2→const latencySamples: number[] = [];
 3→
 4→export function recordLatency(ms: number): void {
 5→  if (latencySamples.length >= MAX_SAMPLES) latencySamples.shift();
 6→  latencySamples.push(ms);
 7→}
 8→
 9→export function getLatencyPercentiles(): {
10→  p50: number;
11→  p95: number;
12→  p99: number;
13→} | null {
14→  if (latencySamples.length === 0) return null;
15→  const sorted = [...latencySamples].sort((a, b) => a - b);
16→  const p = (pct: number) =>
17→    sorted[Math.floor((sorted.length * pct) / 100)] ?? sorted[sorted.length - 1];
18→  return { p50: p(50), p95: p(95), p99: p(99) };
19→}
