 30→/**
 31→ * Creates a fetch wrapper that enforces a timeout via AbortController.
 32→ * Replaces the v5 custom.setHttpOptionsDefaults({ timeout }) mechanism.
 33→ */
 34→function createTimeoutFetch(timeoutMs) {
 35→  return async (url, options = {}) => {
 36→    const controller = new AbortController();
 37→    const timeoutId = setTimeout(() => controller.abort(), timeoutMs);
 38→    try {
 39→      const response = await fetch(url, {
 40→        ...options,
 41→        signal: controller.signal,
 42→      });
 43→      return response;
 44→    } finally {
 45→      clearTimeout(timeoutId);
 46→    }
 47→  };
 48→}
