 50→export async function bootstrapOpenId(configParameter) {
 51→  if (!('issuer' in configParameter) && !('discoveryURL' in configParameter)) {
 52→    return { error: 'missing-issuer-or-discoveryURL' };
 53→  }
 54→  if (!('client_id' in configParameter)) {
 55→    return { error: 'missing-client-id' };
 56→  }
 57→  if (!('client_secret' in configParameter)) {
 58→    return { error: 'missing-client-secret' };
 59→  }
 60→  if (!('server_hostname' in configParameter)) {
 61→    return { error: 'missing-server-hostname' };
 62→  }
 63→
 64→  try {
 65→    //FOR BACKWARD COMPATIBLITY:
 66→    //If we don't put discoverURL into the issuer, it will break already enabled openid instances
 67→    if (configParameter.discoveryURL) {
 68→      configParameter.issuer = configParameter.discoveryURL;
 69→      delete configParameter.discoveryURL;
 70→    }
 71→
 72→    await setupOpenIdClient(configParameter);
 73→  } catch (err) {
 74→    console.error('Error setting up OpenID client:', err);
 75→    return { error: 'configuration-error' };
 76→  }
 77→
 78→  const accountDb = getAccountDb();
 79→  try {
 80→    accountDb.transaction(() => {
 81→      accountDb.mutate('DELETE FROM auth WHERE method = ?', ['openid']);
 82→      accountDb.mutate('UPDATE auth SET active = 0');
 83→      accountDb.mutate(
 84→        "INSERT INTO auth (method, display_name, extra_data, active) VALUES ('openid', 'OpenID', ?, 1)",
 85→        [JSON.stringify(configParameter)],
 86→      );
 87→    });
 88→  } catch (err) {
 89→    console.error('Error updating auth table:', err);
 90→    return { error: 'database-error' };
 91→  }
 92→
 93→  return {};
 94→}
