 96→/**
 97→ * Sets up the OpenID client configuration using the v6 functional API.
 98→ *
 99→ * In v6, discovery() returns a Configuration object that replaces both the
100→ * v5 Issuer and Client instances. For manual issuer configuration (object
101→ * with endpoints), we construct a Configuration directly with ServerMetadata.
102→ */
103→async function setupOpenIdClient(configParameter) {
104→  const redirectUri = new URL(
105→    '/openid/callback',
106→    configParameter.server_hostname,
107→  ).toString();
108→
109→  if (typeof configParameter.issuer === 'string') {
110→    // Auto-discovery: fetch metadata from the issuer URL
111→    // The timeout option (in seconds) applies to discovery and all future requests.
112→    // The [customFetch] option replaces global fetch on the resolved Configuration.
113→    const oidcConfig = await discovery(
114→      new URL(configParameter.issuer),
115→      configParameter.client_id,
116→      configParameter.client_secret,
117→      undefined,
118→      {
119→        timeout: 20,
120→        [customFetch]: createTimeoutFetch(20 * 1000),
121→      },
122→    );
123→    // Attach redirect_uri to the config for use in other functions
124→    oidcConfig[redirectUriSymbol] = redirectUri;
125→    return oidcConfig;
126→  } else {
127→    // Manual configuration: construct ServerMetadata from provided endpoints
128→    const serverMetadata = {
129→      issuer: configParameter.issuer.name,
130→      authorization_endpoint: configParameter.issuer.authorization_endpoint,
131→      token_endpoint: configParameter.issuer.token_endpoint,
132→      userinfo_endpoint: configParameter.issuer.userinfo_endpoint,
133→    };
134→
135→    const oidcConfig = new Configuration(
136→      serverMetadata,
137→      configParameter.client_id,
138→      configParameter.client_secret,
139→    );
140→    oidcConfig[customFetch] = createTimeoutFetch(20 * 1000);
141→    // Attach redirect_uri to the config for use in other functions
142→    oidcConfig[redirectUriSymbol] = redirectUri;
143→    return oidcConfig;
144→  }
145→}
146→
147→// Symbol to store redirect_uri on the Configuration object
148→const redirectUriSymbol = Symbol('redirectUri');
149→
150→export async function loginWithOpenIdSetup(
151→  returnUrl,
152→  firstTimeLoginPassword = '',
153→) {
154→  if (!returnUrl) {
155→    return { error: 'return-url-missing' };
156→  }
157→  if (!isValidRedirectUrl(returnUrl)) {
158→    return { error: 'invalid-return-url' };
159→  }
160→
161→  const accountDb = getAccountDb();
162→
163→  const { countUsersWithUserName } = accountDb.first(
164→    'SELECT count(*) as countUsersWithUserName FROM users WHERE user_name <> ?',
165→    [''],
166→  );
167→  if (countUsersWithUserName === 0) {
168→    const methods = listLoginMethods();
169→    if (methods.some(authMethod => authMethod.method === 'password')) {
170→      const valid = checkPassword(firstTimeLoginPassword);
171→
172→      if (!valid) {
173→        return { error: 'invalid-password' };
174→      }
175→    }
176→  }
177→
178→  let dbConfig = accountDb.first(
179→    'SELECT extra_data FROM auth WHERE method = ?',
180→    ['openid'],
181→  );
182→  if (!dbConfig) {
183→    return { error: 'openid-not-configured' };
184→  }
185→
186→  try {
187→    dbConfig = JSON.parse(dbConfig['extra_data']);
188→  } catch (err) {
189→    console.error('Error parsing OpenID configuration:', err);
190→    return { error: 'openid-setup-failed' };
191→  }
192→
193→  let oidcConfig;
194→  try {
195→    oidcConfig = await setupOpenIdClient(dbConfig);
196→  } catch (err) {
197→    console.error('Error setting up OpenID client:', err);
198→    return { error: 'openid-setup-failed' };
199→  }
200→
201→  const state = randomState();
202→  const code_verifier = randomPKCECodeVerifier();
203→  const code_challenge = await calculatePKCECodeChallenge(code_verifier);
204→
205→  const now_time = Date.now();
206→  const expiry_time = now_time + 300 * 1000;
207→
208→  accountDb.mutate(
209→    'DELETE FROM pending_openid_requests WHERE expiry_time < ?',
210→    [now_time],
211→  );
212→  accountDb.mutate(
213→    'INSERT INTO pending_openid_requests (state, code_verifier, return_url, expiry_time) VALUES (?, ?, ?, ?)',
214→    [state, code_verifier, returnUrl, expiry_time],
215→  );
216→
217→  const redirectUri = oidcConfig[redirectUriSymbol];
218→  const url = buildAuthorizationUrl(oidcConfig, {
219→    redirect_uri: redirectUri,
220→    response_type: 'code',
221→    scope: 'openid email profile',
222→    state,
223→    code_challenge,
224→    code_challenge_method: 'S256',
225→  });
226→
227→  return { url: url.href };
228→}
229→
230→export async function loginWithOpenIdFinalize(body) {
231→  if (!body.code) {
232→    return { error: 'missing-authorization-code' };
233→  }
234→  if (!body.state) {
235→    return { error: 'missing-state' };
236→  }
237→
238→  const accountDb = getAccountDb();
239→  let configFromDb = accountDb.first(
240→    "SELECT extra_data FROM auth WHERE method = 'openid' AND active = 1",
241→  );
242→  if (!configFromDb) {
243→    return { error: 'openid-not-configured' };
244→  }
245→  try {
246→    configFromDb = JSON.parse(configFromDb['extra_data']);
247→  } catch (err) {
248→    console.error('Error parsing OpenID configuration:', err);
249→    return { error: 'openid-setup-failed' };
250→  }
251→  let oidcConfig;
252→  try {
253→    oidcConfig = await setupOpenIdClient(configFromDb);
254→  } catch (err) {
255→    console.error('Error setting up OpenID client:', err);
256→    return { error: 'openid-setup-failed' };
257→  }
258→
259→  const pendingRequest = accountDb.first(
260→    'SELECT code_verifier, return_url FROM pending_openid_requests WHERE state = ? AND expiry_time > ?',
261→    [body.state, Date.now()],
262→  );
263→
264→  if (!pendingRequest) {
265→    return { error: 'invalid-or-expired-state' };
266→  }
267→
268→  const { code_verifier, return_url } = pendingRequest;
269→
270→  try {
271→    const redirectUri = oidcConfig[redirectUriSymbol];
272→    let tokens = null;
273→
274→    if (!configFromDb.authMethod || configFromDb.authMethod === 'openid') {
275→      // Standard OpenID Connect authorization code flow
276→      // In v6, authorizationCodeGrant expects a URL containing the callback parameters
277→      const callbackUrl = new URL(redirectUri);
278→      callbackUrl.searchParams.set('code', body.code);
279→      callbackUrl.searchParams.set('state', body.state);
280→      if (body.iss) {
281→        callbackUrl.searchParams.set('iss', body.iss);
282→      }
283→
284→      tokens = await authorizationCodeGrant(oidcConfig, callbackUrl, {
285→        pkceCodeVerifier: code_verifier,
286→        expectedState: body.state,
287→      });
288→    } else {
289→      // Alternative grant type: use genericGrantRequest for non-standard flows
290→      tokens = await genericGrantRequest(oidcConfig, 'authorization_code', {
291→        code: body.code,
292→        redirect_uri: redirectUri,
293→        code_verifier,
294→      });
295→    }
296→
297→    // In v6, fetchUserInfo requires an expectedSubject parameter.
298→    // Use skipSubjectCheck since the original v5 code did not verify the subject.
299→    const userInfo = await fetchUserInfo(
300→      oidcConfig,
301→      tokens.access_token,
302→      skipSubjectCheck,
303→    );
304→    const identity =
305→      userInfo.preferred_username ??
306→      userInfo.login ??
307→      userInfo.email ??
308→      userInfo.id ??
309→      userInfo.sub;
310→
311→    if (identity == null) {
312→      return { error: 'openid-grant-failed: no identification was found' };
313→    }
314→
315→    let userId = null;
316→    try {
317→      accountDb.transaction(() => {
318→        const { countUsersWithUserName } = accountDb.first(
319→          'SELECT count(*) as countUsersWithUserName FROM users WHERE user_name <> ?',
320→          [''],
321→        );
322→
323→        // Check if user was created by another transaction
324→        const existingUser = accountDb.first(
325→          'SELECT id FROM users WHERE user_name = ?',
326→          [identity],
327→        );
328→
329→        if (
330→          !existingUser &&
331→          (countUsersWithUserName === 0 ||
332→            config.get('userCreationMode') === 'login')
333→        ) {
334→          userId = uuidv4();
335→          accountDb.mutate(
336→            'INSERT INTO users (id, user_name, display_name, enabled, owner, role) VALUES (?, ?, ?, 1, ?, ?)',
337→            [
338→              userId,
339→              identity,
340→              userInfo.name ?? userInfo.email ?? identity,
341→              countUsersWithUserName === 0 ? '1' : '0',
342→              countUsersWithUserName === 0 ? 'ADMIN' : 'BASIC',
343→            ],
344→          );
345→
346→          if (countUsersWithUserName === 0) {
347→            const userFromPasswordMethod = getUserByUsername('');
348→            if (userFromPasswordMethod) {
349→              transferAllFilesFromUser(userId, userFromPasswordMethod.user_id);
350→            }
351→          }
352→        } else {
353→          const { id: userIdFromDb, display_name: displayName } =
354→            accountDb.first(
355→              'SELECT id, display_name FROM users WHERE user_name = ? and enabled = 1',
356→              [identity],
357→            ) || {};
358→
359→          if (userIdFromDb == null) {
360→            throw new Error('openid-grant-failed');
361→          }
362→
363→          if (!displayName && userInfo.name) {
364→            accountDb.mutate('UPDATE users set display_name = ? WHERE id = ?', [
365→              userInfo.name,
366→              userIdFromDb,
367→            ]);
368→          }
369→
370→          userId = userIdFromDb;
371→        }
372→      });
373→    } catch (error) {
374→      if (error.message === 'user-already-exists') {
375→        return { error: 'user-already-exists' };
376→      } else if (error.message === 'openid-grant-failed') {
377→        return { error: 'openid-grant-failed' };
378→      } else {
379→        throw error; // Re-throw other unexpected errors
380→      }
381→    }
382→
383→    const token = uuidv4();
384→
385→    let expiration;
386→    if (config.get('token_expiration') === 'openid-provider') {
387→      // In v6, expires_in is in seconds (optional). Calculate expires_at from it.
388→      const expiresAt = tokens.expires_in
389→        ? Math.floor(Date.now() / 1000) + tokens.expires_in
390→        : null;
391→      expiration = expiresAt ?? TOKEN_EXPIRATION_NEVER;
392→    } else if (config.get('token_expiration') === 'never') {
393→      expiration = TOKEN_EXPIRATION_NEVER;
394→    } else if (typeof config.get('token_expiration') === 'number') {
395→      expiration =
396→        Math.floor(Date.now() / 1000) + config.get('token_expiration');
397→    } else {
398→      expiration = Math.floor(Date.now() / 1000) + 10 * 60; // Default to 10 minutes
399→    }
400→
401→    accountDb.mutate(
402→      'INSERT INTO sessions (token, expires_at, user_id, auth_method) VALUES (?, ?, ?, ?)',
403→      [token, expiration, userId, 'openid'],
404→    );
405→
406→    clearExpiredSessions();
407→
408→    return { url: `${return_url}/openid-cb?token=${token}` };
409→  } catch (err) {
410→    console.error('OpenID grant failed:', err);
411→    return { error: 'openid-grant-failed' };
412→  }
413→}
