415→export function getServerHostname() {
416→  const auth = getAccountDb().first(
417→    'select * from auth WHERE method = ? and active = 1',
418→    ['openid'],
419→  );
420→  if (auth && auth.extra_data) {
421→    try {
422→      const openIdConfig = JSON.parse(auth.extra_data);
423→      return openIdConfig.server_hostname;
424→    } catch (error) {
425→      console.error('Error parsing OpenID configuration:', error);
426→    }
427→  }
428→  return null;
429→}
430→
431→export function isValidRedirectUrl(url) {
432→  const serverHostname = getServerHostname();
433→
434→  if (!serverHostname) {
435→    return false;
436→  }
437→
438→  try {
439→    const redirectUrl = new URL(url);
440→    const serverUrl = new URL(serverHostname);
441→
442→    const hostnamesMatch = redirectUrl.hostname === serverUrl.hostname;
443→    const portsMatch = redirectUrl.port === serverUrl.port;
444→    const schemesMatch = redirectUrl.protocol === serverUrl.protocol;
445→
446→    if (hostnamesMatch && portsMatch && schemesMatch) {
447→      return true;
448→    }
449→
450→    console.warn(
451→      `[openid] Blocked redirect URL: ${url} (server: ${serverHostname})`,
452→    );
453→    return false;
454→  } catch {
455→    return false;
456→  }
457→}
