162→// Initiates an OAuth bank-link flow. Generates a UUID state for CSRF protection,
163→// stores a pending session row, calls Enable Banking POST /auth, and returns the
164→// bank's redirect URL plus the state token for the client to poll with.
165→app.post(
166→  '/create-auth',
167→  handleError(async (req, res) => {
168→    const { aspspName, aspspCountry } = req.body || {};
169→
170→    // UUID state for CSRF protection - validated in /callback.
171→    const state = crypto.randomUUID();
172→
173→    const db = getAccountDb();
174→
175→    // Insert a pending session. id = state is a temporary placeholder until
176→    // /callback exchanges the code and sets id = real session_id.
177→    db.mutate(
178→      'INSERT INTO eb_sessions (id, state, aspsp_name, aspsp_country) VALUES (?, ?, ?, ?)',
179→      [state, state, aspspName ?? null, aspspCountry ?? null],
180→    );
181→
182→    const redirectUrl =
183→      process.env.ENABLE_BANKING_REDIRECT_URL ||
184→      'http://localhost:5006/enablebanking/callback';
185→
186→    const result = await createAuth({
187→      aspspName,
188→      aspspCountry,
189→      redirectUrl,
190→      state,
191→    });
192→
193→    res.send({ status: 'ok', data: { url: result.url, state } });
194→  }),
195→);
196→
197→// Polls for session completion after the OAuth callback. Returns normalized
198→// accounts when the session is ready (accounts column populated), otherwise
199→// returns an empty data object for the client to retry.
200→//
201→// CRITICAL: Raw EB account objects do NOT carry aspsp_name - it lives only at
202→// the session level (stored in eb_sessions.aspsp_name at create-auth time).
203→// We enrich each account before passing to normalizeAccount() so the institution
204→// field is populated and SelectLinkedAccountsModal shows the bank name.
205→app.post(
206→  '/get-accounts',
207→  handleError(async (req, res) => {
208→    const { state } = req.body || {};
209→
210→    const db = getAccountDb();
211→    const sessionRow = db.first('SELECT * FROM eb_sessions WHERE state = ?', [
212→      state,
213→    ]);
214→
215→    if (!sessionRow || !sessionRow.accounts) {
216→      // Session not yet complete - client should retry.
217→      return res.send({ status: 'ok', data: {} });
218→    }
219→
220→    const parsedAccounts = JSON.parse(sessionRow.accounts as string);
221→    const accounts = parsedAccounts.map(account =>
222→      normalizeAccount(
223→        { ...account, aspsp_name: sessionRow.aspsp_name },
224→        sessionRow.id,
225→      ),
226→    );
227→
228→    res.send({ status: 'ok', data: { accounts } });
229→  }),
230→);
