232→// Fetches and normalizes transactions for an account from startDate onward.
233→// Looks up the account in eb_account_map by actual_account_id OR eb_account_uid
234→// (syncAccount() may pass either depending on call context).
235→//
236→// NULL GUARD: If the account has not been mapped (link flow not completed),
237→// returns ACCOUNT_NOT_MAPPED error in status:ok wrapper so loot-core's post()
238→// helper unwraps it and downloadEnableBankingTransactions() can check error_code.
239→// This matches the GoCardless error pattern (app-gocardless.js:213-222).
240→app.post(
241→  '/transactions',
242→  handleError(async (req, res) => {
243→    const { accountId, startDate } = req.body || {};
244→
245→    const db = getAccountDb();
246→
247→    const mapRow = db.first(
248→      'SELECT * FROM eb_account_map WHERE actual_account_id = ? OR eb_account_uid = ?',
249→      [accountId, accountId],
250→    );
251→
252→    if (!mapRow) {
253→      return res.send({
254→        status: 'ok',
255→        data: { error_code: 'ACCOUNT_NOT_MAPPED', error_type: 'SYNC_ERROR' },
256→      });
257→    }
258→
259→    const ebAccountUid = mapRow.eb_account_uid;
260→
261→    // actual_account_id from the map row is the Actual Budget UUID (populated
262→    // at link time by /update-account-map). We use it for the sync log so that
263→    // /sync-status queries by Actual UUID succeed. accountId in req.body may be
264→    // an EB UID when called from the scheduler, so we never use it for logging.
265→    const logActualId = mapRow.actual_account_id || accountId;
266→    const logEbUid = mapRow.eb_account_uid;
267→
268→    try {
269→      const { booked, pending } = await getTransactions(
270→        ebAccountUid,
271→        startDate,
272→      );
273→      const normalizedBooked = booked.map(t => normalizeTransaction(t, true));
274→      const normalizedPending = pending.map(t =>
275→        normalizeTransaction(t, false),
276→      );
277→
278→      const balancesData = await getBalances(ebAccountUid);
279→      const extractedBalance = extractBalance(
280→        balancesData.balances ?? balancesData,
281→      );
282→
283→      db.mutate(
284→        `INSERT INTO eb_sync_log
285→          (actual_account_id, eb_account_uid, status, transactions_added)
286→          VALUES (?, ?, 'ok', ?)`,
287→        [
288→          logActualId,
289→          logEbUid,
290→          normalizedBooked.length + normalizedPending.length,
291→        ],
292→      );
293→
294→      res.send({
295→        status: 'ok',
296→        data: {
297→          transactions: { all: [...normalizedBooked, ...normalizedPending] },
298→          balances: extractedBalance,
299→          startingBalance: extractedBalance,
300→        },
301→      });
302→    } catch (err) {
303→      db.mutate(
304→        `INSERT INTO eb_sync_log
305→          (actual_account_id, eb_account_uid, status, error_message)
306→          VALUES (?, ?, 'error', ?)`,
307→        [logActualId, logEbUid, err.message ?? String(err)],
308→      );
309→      throw err;
310→    }
311→  }),
312→);
