 1→import type { Request, Response, NextFunction } from 'express';
 2→import * as expressWinston from 'express-winston';
 3→import * as winston from 'winston';
 4→
 5→import logger from './logger';
 6→import { validateSession } from './validate-user';
 7→
 8→async function errorMiddleware(
 9→  err: Error,
10→  req: Request,
11→  res: Response,
12→  next: NextFunction,
13→): Promise<void> {
14→  if (res.headersSent) {
15→    // If you call next() with an error after you have started writing the response
16→    // (for example, if you encounter an error while streaming the response
17→    // to the client), the Express default error handler closes
18→    // the connection and fails the request.
19→
20→    // So when you add a custom error handler, you must delegate
21→    // to the default Express error handler, when the headers
22→    // have already been sent to the client
23→    // Source: https://expressjs.com/en/guide/error-handling.html
24→    return next(err);
25→  }
26→
27→  logger.error('Error on endpoint', {
28→    requestUrl: req.url,
29→    stacktrace: err.stack,
30→  });
31→  res.status(500).send({ status: 'error', reason: 'internal-error' });
32→}
33→
34→const validateSessionMiddleware = async (
35→  req: Request,
36→  res: Response,
37→  next: NextFunction,
38→): Promise<void> => {
39→  const session = await validateSession(req, res);
40→  if (!session) {
41→    return;
42→  }
43→
44→  res.locals = session;
45→  next();
46→};
47→
48→const requestLoggerMiddleware = expressWinston.logger({
49→  transports: [new winston.transports.Console()],
50→  format: winston.format.combine(
51→    ...(Object.prototype.hasOwnProperty.call(process.env, 'NO_COLOR')
52→      ? []
53→      : [winston.format.colorize()]),
54→    winston.format.timestamp(),
55→    winston.format.printf(args => {
56→      const { timestamp, level, meta } = args as unknown as {
57→        timestamp: string;
58→        level: string;
59→        meta: {
60→          res: { statusCode: number };
61→          req: { method: string; url: string };
62→        };
63→      };
64→      const { res, req } = meta;
65→
66→      return `${timestamp} ${level}: ${req.method} ${res.statusCode} ${req.url}`;
67→    }),
68→  ),
69→});
70→
71→export { validateSessionMiddleware, errorMiddleware, requestLoggerMiddleware };
