236→// ---------------------------------------------------------------------------
237→// useConsentExpiryNotifications
238→// ---------------------------------------------------------------------------
239→
240→/**
241→ * Side-effect hook that routes consent expiry warnings through the Redux
242→ * Notifications system as sticky warnings. Call from FinancesApp.
243→ *
244→ * Replaces the ConsentExpiryBanner standalone component:
245→ * - Single session  → per-session notification with Re-authorize button
246→ * - Multiple sessions → aggregated notification with Manage bank sync button
247→ * - Daily-dismiss via localStorage preserved (isDismissed / dismiss helpers)
248→ * - Two-pass localStorage cleanup on each sessions change
249→ */
250→export function useConsentExpiryNotifications(): void {
251→  const { sessions } = useConsentExpiry();
252→  const dispatch = useDispatch();
253→  const navigate = useNavigate();
254→
255→  // Stable deps: re-run only when session count or IDs change, not on
256→  // referential array identity changes.
257→  const sessionCount = sessions.length;
258→  const sessionIdsKey = sessions.map(s => s.sessionId).join(',');
259→
260→  useEffect(() => {
261→    // Two-pass localStorage cleanup: collect stale keys first, then delete.
262→    // Deleting during index iteration corrupts i and skips keys.
263→    const today = new Date().toDateString();
264→    const keysToDelete: string[] = [];
265→    for (let i = 0; i < localStorage.length; i++) {
266→      const key = localStorage.key(i);
267→      if (key?.startsWith('consent-dismissed-') && !key.endsWith(today)) {
268→        keysToDelete.push(key);
269→      }
270→    }
271→    for (const key of keysToDelete) {
272→      localStorage.removeItem(key);
273→    }
274→
275→    if (sessionCount === 0) return;
276→
277→    const visibleSessions = sessions.filter(s => !isDismissed(s.sessionId));
278→
279→    if (visibleSessions.length === 0) return;
280→
281→    if (visibleSessions.length === 1) {
282→      const session = visibleSessions[0];
283→      const bankName = session.aspspName ?? 'Bank';
284→      const isExpired = session.urgency === 'expired';
285→
286→      dispatch(
287→        addNotification({
288→          notification: {
289→            id: `consent-expiry-${session.sessionId}`,
290→            type: 'warning',
291→            sticky: true,
292→            title: isExpired
293→              ? 'Bank connection expired'
294→              : 'Bank connection expiring',
295→            message: isExpired
296→              ? `${bankName} bank connection expired - re-authorize to resume automatic sync`
297→              : `${bankName} bank connection expires ${formatExpiryDate(session.validUntil)}`,
298→            button: {
299→              title: 'Re-authorize',
300→              action: () => {
301→                dispatch(
302→                  pushModal({
303→                    modal: {
304→                      name: 'enablebanking-external-msg',
305→                      options: {
306→                        sessionId: session.sessionId,
307→                        aspspName: session.aspspName ?? undefined,
308→                        aspspCountry: session.aspspCountry ?? undefined,
309→                        reauth: true,
310→                      },
311→                    },
312→                  }),
313→                );
314→              },
315→            },
316→            onClose: () => {
317→              dismiss(session.sessionId);
318→            },
319→          },
320→        }),
321→      );
322→    } else {
323→      // Multiple sessions: single aggregated notification
324→      const expiredCount = visibleSessions.filter(
325→        s => s.urgency === 'expired',
326→      ).length;
327→      const baseMessage = `${visibleSessions.length} bank connections need re-authorization`;
328→      const message =
329→        expiredCount > 0
330→          ? `${baseMessage} (${expiredCount} expired)`
331→          : baseMessage;
332→
333→      dispatch(
334→        addNotification({
335→          notification: {
336→            id: 'consent-expiry-multi',
337→            type: 'warning',
338→            sticky: true,
339→            title: 'Bank connections expiring',
340→            message,
341→            button: {
342→              title: 'Manage bank sync',
343→              action: () => {
344→                navigate('/bank-sync');
345→              },
346→            },
347→            onClose: () => {
348→              for (const s of visibleSessions) {
349→                dismiss(s.sessionId);
350→              }
351→            },
352→          },
353→        }),
354→      );
355→    }
356→    // eslint-disable-next-line react-hooks/exhaustive-deps
357→  }, [sessionCount, sessionIdsKey]);
358→}
