 3→// 2. Enforces sufficient timeout via updatedInput (pre-push hook runs build/test)
 4→const fs = require('fs');
 5→
 6→let input;
 7→try {
 8→  input = JSON.parse(fs.readFileSync(0, 'utf8'));
 9→} catch (e) {
10→  // Malformed stdin - fail-open (don't block pushes if hook framework is broken)
11→  process.exit(0);
12→}
13→
14→if (!input || input.tool_name !== 'Bash') process.exit(0);
15→
16→const cmd = (input.tool_input && input.tool_input.command) || '';
17→
18→// Only care about git push commands
19→if (!/\bgit\s+push\b/.test(cmd)) process.exit(0);
20→
21→// Strip quoted strings before checking for --no-verify to avoid false positives
22→// on chained commands like: git commit -m "removed --no-verify" && git push
23→const cmdStripped = cmd.replace(/"(?:[^"\\]|\\.)*"|'[^']*'/g, '""');
24→
25→// Block --no-verify
26→if (/--no-verify/.test(cmdStripped)) {
27→  process.stderr.write(
28→    '[push-guard] --no-verify bypasses the pre-push hook entirely. ' +
29→    'Use targeted skips instead:\n' +
30→    '  SKIP_TEST=1 git push       (skip tests only)\n' +
31→    '  SKIP_BUILD=1 git push      (skip build only)\n' +
32→    '  SKIP_TYPECHECK=1 git push  (skip typecheck only)\n' +
33→    'Or add a .prepushrc file to the project with: skip-test / skip-build / scripts=typecheck build'
34→  );
35→  process.exit(2);
36→}
37→
38→// Enforce timeout - auto-fix via updatedInput instead of blocking
39→const timeout = input.tool_input && input.tool_input.timeout;
40→const MIN_TIMEOUT = 600000;
41→
42→if (!timeout || timeout < MIN_TIMEOUT) {
43→  const fixed = Object.assign({}, input.tool_input, { timeout: MIN_TIMEOUT });
44→  process.stdout.write(JSON.stringify({
45→    permissionDecision: 'allow',
46→    updatedInput: fixed,
47→    additionalContext: '[push-guard] Auto-set timeout to ' + MIN_TIMEOUT +
48→      'ms (10 min) for pre-push hook. Was: ' + (timeout || '120000 (default)') + '.'
49→  }));
50→  process.exit(0);
51→}
52→
53→process.exit(0);
