275→
276→    1. Add a new hook `useOperationalAlerts()` at the end of the file. This follows the same side-effect pattern as `useConsentExpiryNotifications()` and `useBankSyncNotification()`:
277→
278→       ```typescript
279→       // ---------------------------------------------------------------------------
280→       // useOperationalAlerts
281→       // ---------------------------------------------------------------------------
282→
283→       type ServerAlert = {
284→         id: string;
285→         event_type: string;
286→         message: string;
287→         timestamp: string;
288→         severity: 'info' | 'warning' | 'error';
289→       };
290→
291→       /**
292→        * Side-effect hook that polls the sync-server for operational alerts
293→        * (sync failures, consent expiry warnings, auth failure bursts) and
294→        * surfaces them as in-app notifications via the Redux Notifications system.
295→        *
296→        * Polls every 60 seconds. Acknowledges alerts on the server when the
297→        * user dismisses the notification (onClose callback).
298→        *
299→        * Per user decision obs-2: "Extend the existing in-app Notifications
300→        * system (from Phase 6 migration) for user-visible alerts."
301→        */
302→       export function useOperationalAlerts(): void {
303→         const dispatch = useDispatch();
304→         const status = useSyncServerStatus();
305→         const knownAlertIds = useRef<Set<string>>(new Set());
306→
307→         useEffect(() => {
308→           if (status !== 'online') return;
309→
310→           let active = true;
311→
312→           async function poll() {
313→             try {
314→               const result = await send('operational-alerts');
315→               if (!active || !result?.alerts) return;
316→
317→               const alerts: ServerAlert[] = result.alerts;
318→
319→               for (const alert of alerts) {
320→                 if (knownAlertIds.current.has(alert.id)) continue;
321→                 knownAlertIds.current.add(alert.id);
322→
323→                 const notificationType: 'error' | 'warning' | 'message' =
324→                   alert.severity === 'error'
325→                     ? 'error'
326→                     : alert.severity === 'warning'
327→                       ? 'warning'
328→                       : 'message';
329→
330→                 dispatch(
331→                   addNotification({
332→                     notification: {
333→                       id: `op-alert-${alert.id}`,
334→                       type: notificationType,
335→                       sticky: true,
336→                       title: formatAlertTitle(alert.event_type),
337→                       message: alert.message,
338→                       onClose: () => {
339→                         // Acknowledge on server so it doesn't re-appear
340→                         send('operational-alerts-acknowledge', {
341→                           alertId: alert.id,
342→                         }).catch(() => {});
343→                       },
344→                     },
345→                   }),
346→                 );
347→               }
348→             } catch {
349→               // Server unreachable - ignore, will retry next interval
350→             }
351→           }
352→
353→           // Poll immediately, then every 60 seconds
354→           poll();
355→           const interval = setInterval(poll, 60_000);
356→
357→           return () => {
358→             active = false;
359→             clearInterval(interval);
360→           };
361→         }, [status, dispatch]);
362→       }
363→
364→       function formatAlertTitle(eventType: string): string {
365→         switch (eventType) {
366→           case 'sync_failure':
367→             return 'Sync failed';
368→           case 'consent_expiry':
369→             return 'Bank connection expiring';
370→           case 'auth_failure_burst':
371→             return 'Repeated login failures';
372→           default:
373→             return 'Operational alert';
374→         }
375→       }
376→       ```
