 9→async function errorMiddleware(
10→  err: Error,
11→  req: Request,
12→  res: Response,
13→  next: NextFunction,
14→): Promise<void> {
15→  if (res.headersSent) {
16→    // If you call next() with an error after you have started writing the response
17→    // (for example, if you encounter an error while streaming the response
18→    // to the client), the Express default error handler closes
19→    // the connection and fails the request.
20→
21→    // So when you add a custom error handler, you must delegate
22→    // to the default Express error handler, when the headers
23→    // have already been sent to the client
24→    // Source: https://expressjs.com/en/guide/error-handling.html
25→    return next(err);
26→  }
27→
28→  logger.error('Error on endpoint', {
29→    url: req.url,
30→    hasSession: !!req.headers['x-actual-token'],
31→    errorClass: err.constructor.name,
32→    stack: err.stack,
33→  });
34→  res.status(500).send({ status: 'error', reason: 'internal-error' });
35→}
36→
37→const validateSessionMiddleware = async (
38→  req: Request,
39→  res: Response,
40→  next: NextFunction,
41→): Promise<void> => {
42→  const session = await validateSession(req, res);
43→  if (!session) {
44→    return;
45→  }
46→
47→  res.locals = session;
48→  next();
49→};
50→
51→const requestLoggerMiddleware = expressWinston.logger({
52→  transports: [new winston.transports.Console()],
53→  format: winston.format.combine(
54→    ...(Object.prototype.hasOwnProperty.call(process.env, 'NO_COLOR')
55→      ? []
56→      : [winston.format.colorize()]),
57→    winston.format.timestamp(),
58→    winston.format.printf(args => {
59→      const { timestamp, level, meta } = args as unknown as {
60→        timestamp: string;
61→        level: string;
62→        meta: {
63→          res: { statusCode: number };
64→          req: { method: string; url: string };
65→        };
66→      };
67→      const { res, req } = meta;
68→
69→      return `${timestamp} ${level}: ${req.method} ${res.statusCode} ${req.url}`;
70→    }),
71→  ),
72→});
73→
74→function latencyMiddleware(req: Request, res: Response, next: NextFunction): void {
75→  const start = Date.now();
76→  res.on('finish', () => recordLatency(Date.now() - start));
77→  next();
78→}
79→
80→export { validateSessionMiddleware, errorMiddleware, requestLoggerMiddleware, latencyMiddleware };
