 30→async function syncOneAccount(account: AccountRow): Promise<void> {
 31→  const db = getAccountDb();
 32→
 33→  // Derive sinceDate from last successful sync (epoch integer -> YYYY-MM-DD).
 34→  const row = db.first(
 35→    'SELECT synced_at FROM eb_sync_log WHERE actual_account_id = ? ORDER BY id DESC LIMIT 1',
 36→    [account.actual_account_id],
 37→  );
 38→  const sinceDate = row?.synced_at
 39→    ? new Date(Number(row.synced_at) * 1000).toISOString().split('T')[0]
 40→    : new Date(Date.now() - 90 * 24 * 3600 * 1000).toISOString().split('T')[0];
 41→
 42→  const { booked, pending } = await getTransactions(
 43→    account.eb_account_uid,
 44→    sinceDate,
 45→  );
 46→  await getBalances(account.eb_account_uid);
 47→
 48→  const allNormalized = [
 49→    ...booked.map(t => normalizeTransaction(t, true)),
 50→    ...pending.map(t => normalizeTransaction(t, false)),
 51→  ];
 52→
 53→  db.mutate(
 54→    `INSERT INTO eb_sync_log (actual_account_id, eb_account_uid, status, transactions_added)
 55→     VALUES (?, ?, 'ok', ?)`,
 56→    [account.actual_account_id, account.eb_account_uid, allNormalized.length],
 57→  );
 58→
 59→  logger.info('Synced account', {
 60→    accountId: account.actual_account_id,
 61→    transactions: allNormalized.length,
 62→  });
 63→}
