31→/**
32→ * Creates a fetch wrapper that enforces a timeout via AbortController.
33→ * Replaces the v5 custom.setHttpOptionsDefaults({ timeout }) mechanism.
34→ */
35→function createTimeoutFetch(timeoutMs) {
36→  return async (url, options = {}) => {
37→    const controller = new AbortController();
38→    const timeoutId = setTimeout(() => controller.abort(), timeoutMs);
39→    try {
40→      const response = await fetch(url, {
41→        ...options,
42→        signal: controller.signal,
43→      });
44→      return response;
45→    } finally {
46→      clearTimeout(timeoutId);
47→    }
48→  };
49→}
