115→          );
116→
117→          if (packageJson.name === '@actual-app/sync-server') {
118→            return packageJson;
119→          }
120→        }
121→
122→        currentPath = resolve(join(currentPath, '..')); // Move up one directory
123→        directoriesSearched++;
124→      }
125→    } catch (error) {
126→      console.error('Error while searching for package.json:', error);
127→    }
