 52→function AppInner() {
 53→  const [budgetId] = useMetadataPref('id');
 54→  const [cloudFileId] = useMetadataPref('cloudFileId');
 55→  const { t } = useTranslation();
 56→  const { showBoundary: showErrorBoundary } = useErrorBoundary();
 57→  const dispatch = useDispatch();
 58→  const userData = useSelector(state => state.user.data);
 59→
 60→  useEffect(() => {
 61→    setI18NextLanguage(null);
 62→  }, []);
 63→
 64→  useEffect(() => {
 65→    const maybeUpdate = async <T,>(cb?: () => T): Promise<T | void> => {
 66→      if (global.Actual.isUpdateReadyForDownload()) {
 67→        dispatch(
 68→          setAppState({
 69→            loadingText: t('Downloading and applying update...'),
 70→          }),
 71→        );
 72→        await global.Actual.applyAppUpdate();
 73→      }
 74→      return cb?.();
 75→    };
 76→
 77→    async function init() {
 78→      await maybeUpdate();
 79→      dispatch(
 80→        setAppState({
 81→          loadingText: t(
 82→            'Initializing the connection to the local database...',
 83→          ),
 84→        }),
 85→      );
 86→      await initConnection();
 87→
 88→      // Load any global prefs
 89→      dispatch(
 90→        setAppState({
 91→          loadingText: t('Loading global preferences...'),
 92→        }),
 93→      );
 94→      await dispatch(loadGlobalPrefs());
 95→
 96→      // Open the last opened budget, if any
 97→      dispatch(
 98→        setAppState({
 99→          loadingText: t('Opening last budget...'),
100→        }),
101→      );
102→      const budgetId = await send('get-last-opened-backup');
103→      if (budgetId) {
104→        await dispatch(loadBudget({ id: budgetId }));
105→
106→        // Check to see if this file has been remotely deleted (but
107→        // don't block on this in case they are offline or something)
108→        dispatch(
109→          setAppState({
110→            loadingText: t('Retrieving remote files...'),
111→          }),
112→        );
113→
114→        const files = await send('get-remote-files');
115→        if (files) {
116→          const remoteFile = files.find(f => f.fileId === cloudFileId);
117→          if (remoteFile && remoteFile.deleted) {
118→            dispatch(closeBudget());
119→          }
120→        }
121→
122→        await maybeUpdate();
123→      }
124→    }
125→
126→    async function initAll() {
127→      await Promise.all([installPolyfills(), init()]);
128→      dispatch(setAppState({ loadingText: null }));
129→    }
130→
131→    initAll().catch(showErrorBoundary);
132→    // Removed cloudFileId & t from dependencies to prevent hard crash when closing budget in Electron
133→    // oxlint-disable-next-line react-hooks/exhaustive-deps
134→  }, [dispatch, showErrorBoundary]);
135→
136→  useEffect(() => {
137→    if (userData?.tokenExpired) {
138→      dispatch(
139→        addNotification({
140→          notification: {
141→            type: 'error',
142→            id: 'login-expired',
143→            title: t('Login expired'),
144→            sticky: true,
145→            message: t('Login expired, please log in again.'),
146→            button: {
147→              title: t('Go to login'),
148→              action: () => {
149→                dispatch(signOut());
150→              },
151→            },
152→          },
153→        }),
154→      );
155→    }
156→  }, [dispatch, t, userData?.tokenExpired]);
157→
158→  return budgetId ? <FinancesApp /> : <ManagementApp />;
159→}
