184→      if (hiddenScrollbars !== hasHiddenScrollbars()) {
185→        setHiddenScrollbars(hasHiddenScrollbars());
186→      }
187→    }
188→
189→    let isSyncing = false;
190→
191→    async function onVisibilityChange() {
