200→    window.addEventListener('focus', checkScrollbars);
201→    window.addEventListener('visibilitychange', onVisibilityChange);
202→
203→    return () => {
204→      window.removeEventListener('focus', checkScrollbars);
205→      window.removeEventListener('visibilitychange', onVisibilityChange);
206→    };
207→  }, [dispatch, hiddenScrollbars]);
