222→                    height: '100%',
223→                    display: 'flex',
224→                    flexDirection: 'column',
225→                  }}
226→                >
227→                  <View
228→                    key={hiddenScrollbars ? 'hidden-scrollbars' : 'scrollbars'}
229→                    style={{
