 50→function NarrowNotSupported({
 51→  redirectTo = '/budget',
 52→  children,
 53→}: {
 54→  redirectTo?: string;
 55→  children: ReactElement;
 56→}) {
 57→  const { isNarrowWidth } = useResponsive();
