360→// ---------------------------------------------------------------------------
361→// useOperationalAlerts
362→// ---------------------------------------------------------------------------
363→
364→type ServerAlert = {
365→  id: string;
366→  event_type: string;
367→  message: string;
368→  timestamp: string;
369→  severity: 'info' | 'warning' | 'error';
370→};
371→
372→/**
373→ * Side-effect hook that polls the sync-server for operational alerts
374→ * (sync failures, consent expiry warnings, auth failure bursts) and
375→ * surfaces them as in-app notifications via the Redux Notifications system.
376→ *
377→ * Polls every 60 seconds. Acknowledges alerts on the server when the
378→ * user dismisses the notification (onClose callback).
379→ *
380→ * Per user decision obs-2: "Extend the existing in-app Notifications
381→ * system (from Phase 6 migration) for user-visible alerts."
382→ */
383→export function useOperationalAlerts(): void {
384→  const dispatch = useDispatch();
385→  const status = useSyncServerStatus();
386→  const knownAlertIds = useRef<Set<string>>(new Set());
387→
388→  useEffect(() => {
389→    if (status !== 'online') return;
390→
391→    let active = true;
392→
393→    async function poll() {
394→      try {
395→        const result = await send('operational-alerts');
396→        if (!active || !result?.alerts) return;
397→
398→        const alerts: ServerAlert[] = result.alerts;
399→
400→        for (const alert of alerts) {
401→          if (knownAlertIds.current.has(alert.id)) continue;
402→          knownAlertIds.current.add(alert.id);
403→
404→          const notificationType: 'error' | 'warning' | 'message' =
405→            alert.severity === 'error'
406→              ? 'error'
407→              : alert.severity === 'warning'
408→                ? 'warning'
409→                : 'message';
410→
411→          dispatch(
412→            addNotification({
413→              notification: {
414→                id: `op-alert-${alert.id}`,
415→                type: notificationType,
416→                sticky: true,
417→                title: formatAlertTitle(alert.event_type),
418→                message: alert.message,
419→                onClose: () => {
420→                  // Acknowledge on server so it doesn't re-appear
421→                  send('operational-alerts-acknowledge', {
422→                    alertId: alert.id,
423→                  }).catch(() => {});
424→                },
425→              },
426→            }),
427→          );
428→        }
429→      } catch {
430→        // Server unreachable - ignore, will retry next interval
431→      }
432→    }
433→
434→    // Poll immediately, then every 60 seconds
435→    poll();
436→    const interval = setInterval(poll, 60_000);
437→
438→    return () => {
439→      active = false;
440→      clearInterval(interval);
441→    };
442→  }, [status, dispatch]);
443→}
444→
445→function formatAlertTitle(eventType: string): string {
446→  switch (eventType) {
447→    case 'sync_failure':
448→      return 'Sync failed';
449→    case 'consent_expiry':
450→      return 'Bank connection expiring';
451→    case 'auth_failure_burst':
452→      return 'Repeated login failures';
453→    default:
454→      return 'Operational alert';
455→  }
456→}
