458→// ---------------------------------------------------------------------------
459→// useBankSyncNotification
460→// ---------------------------------------------------------------------------
461→
462→/**
463→ * Side-effect hook that routes bank-sync-in-progress status through the Redux
464→ * Notifications system. Dispatches a sticky message while accounts are syncing
465→ * and removes it when sync completes. Call from FinancesApp.
466→ *
467→ * Replaces the BankSyncStatus standalone component.
468→ */
469→export function useBankSyncNotification(): void {
470→  const accountsSyncing = useSelector(
471→    (state: { account: { accountsSyncing: string[] } }) =>
472→      state.account.accountsSyncing,
473→  );
474→  const dispatch = useDispatch();
475→  // Track whether a sync notification is currently active to avoid orphaning
476→  // the notification if the component re-renders between sync start and end.
477→  const wasActive = useRef<boolean>(false);
478→
479→  useEffect(() => {
480→    if (accountsSyncing.length > 0) {
481→      dispatch(
482→        addNotification({
483→          notification: {
484→            id: 'bank-sync-in-progress',
485→            type: 'message',
486→            sticky: true,
487→            message: `Syncing... ${accountsSyncing.length} accounts remaining`,
488→          },
489→        }),
490→      );
491→      wasActive.current = true;
492→    } else if (wasActive.current === true) {
493→      dispatch(removeNotification({ id: 'bank-sync-in-progress' }));
494→      wasActive.current = false;
495→    }
496→  }, [accountsSyncing.length, dispatch]);
497→}
