106→export function EnableBankingExternalMsgModal({
107→  sessionId,
108→  aspspName,
109→  aspspCountry,
110→  reauth = false,
111→}: EnableBankingExternalMsgModalProps = {}) {
112→  const { t } = useTranslation();
113→  const dispatch = useDispatch();
114→  const [language] = useGlobalPref('language');
115→
116→  const browserTimezone =
117→    Intl.DateTimeFormat().resolvedOptions().timeZone || '';
118→  const browserLocale = language || navigator.language || 'en-US';
119→  const detectedCountry = getCountryFromBrowser(
120→    browserTimezone,
121→    browserLocale,
122→    COUNTRY_OPTIONS,
123→  );
124→
125→  const [waiting, setWaiting] = useState<string | null>(null);
126→  const [success, setSuccess] = useState<boolean>(false);
127→  // In re-auth mode, pre-fill bank and country from props to bypass the picker.
128→  // This ensures onJump() doesn't silently abort due to the guard
129→  // `if (!selectedBankId || !country) return`.
130→  const [selectedBankId, setSelectedBankId] = useState<string | undefined>(
131→    reauth ? aspspName : undefined,
132→  );
133→  const [country, setCountry] = useState<string | undefined>(
134→    reauth ? aspspCountry : detectedCountry,
135→  );
136→  const [error, setError] = useState<{
137→    code: 'unknown' | 'timeout';
138→    message?: string;
139→  } | null>(null);
140→
141→  const {
142→    data: bankOptions,
143→    isLoading: isBankOptionsLoading,
144→    isError: isBankOptionError,
145→  } = useAvailableBanks(country ?? '');
146→
147→  const { configured: isConfigured, isLoading: isConfigurationLoading } =
148→    useEnableBankingStatus();
149→
150→  async function onJump() {
151→    if (!selectedBankId || !country) return;
152→
153→    setError(null);
154→    setWaiting('browser');
155→
156→    try {
157→      const { accounts } = await authorizeEnableBank(selectedBankId, country);
158→
159→      if (reauth) {
160→        // Re-auth mode: swap the old session for the new one in eb_account_map.
161→        // The new session_id is shared by all accounts from the same OAuth flow.
162→        if (!accounts || accounts.length === 0) {
163→          setError({
164→            code: 'unknown',
165→            message: t('No accounts returned from re-authorization'),
166→          });
167→          setWaiting(null);
168→          return;
169→        }
170→
171→        const newSessionId = accounts[0].session_id;
172→
173→        await send('enablebanking-reauth-complete', {
174→          newSessionId,
175→          oldSessionId: sessionId,
176→        });
177→
178→        // Trigger an immediate sync so the user sees fresh data after re-auth.
179→        send('accounts-bank-sync', { ids: [] }).catch(() => {});
180→
181→        setWaiting(null);
182→        setSuccess(true);
183→      } else {
184→        dispatch(
185→          pushModal({
186→            modal: {
187→              name: 'select-linked-accounts',
188→              options: {
189→                externalAccounts: accounts,
190→                syncSource: 'enableBanking',
191→              },
192→            },
193→          }),
194→        );
195→
196→        setWaiting(null);
197→        setSuccess(true);
198→      }
199→    } catch (err: unknown) {
200→      const message =
201→        err instanceof globalThis.Error ? err.message : String(err);
202→      setError({
203→        code: message === 'timeout' ? 'timeout' : 'unknown',
204→        message: message !== 'timeout' ? message : undefined,
205→      });
206→      setWaiting(null);
207→    }
208→  }
209→
210→  const renderLinkButton = () => {
211→    return (
212→      <View style={{ gap: 10 }}>
213→        <FormField>
214→          <FormLabel
215→            title={t('Choose your country:')}
216→            htmlFor="country-field"
217→          />
218→          <Autocomplete
219→            strict
220→            highlightFirst
221→            suggestions={COUNTRY_OPTIONS}
222→            onSelect={setCountry}
223→            value={country}
224→            inputProps={{
225→              id: 'country-field',
226→              placeholder: t('(please select)'),
227→            }}
228→          />
229→        </FormField>
230→
231→        {isBankOptionError ? (
232→          <Error>
233→            <Trans>
234→              Failed loading available banks. Enable Banking may not be
235→              configured correctly. Please check your server settings.
236→            </Trans>
237→          </Error>
238→        ) : (
239→          country &&
240→          (isBankOptionsLoading ? (
241→            t('Loading banks...')
242→          ) : (
243→            <FormField>
244→              <FormLabel title={t('Choose your bank:')} htmlFor="bank-field" />
245→              <Autocomplete
246→                focused
247→                strict
248→                highlightFirst
249→                suggestions={bankOptions}
250→                onSelect={setSelectedBankId}
251→                value={selectedBankId}
252→                inputProps={{
253→                  id: 'bank-field',
254→                  placeholder: t('(please select)'),
255→                }}
256→              />
257→            </FormField>
258→          ))
259→        )}
260→
261→        <Warning>
262→          <Trans>
263→            By enabling bank sync, you will be granting Enable Banking (a third
264→            party service) read-only access to your account&apos;s transaction
265→            history. This service is not affiliated with Actual in any way. Make
266→            sure you&apos;ve read and understand Enable Banking&apos;s{' '}
267→            <Link
268→              variant="external"
269→              to="https://enablebanking.com/privacy-policy/"
270→              linkColor="purple"
271→            >
272→              Privacy Policy
273→            </Link>{' '}
274→            before proceeding.
275→          </Trans>
276→        </Warning>
277→
278→        <View style={{ flexDirection: 'row', gap: 10, alignItems: 'center' }}>
279→          <Button
280→            variant="primary"
281→            autoFocus
282→            style={{
283→              padding: '10px 0',
284→              fontSize: 15,
285→              fontWeight: 600,
286→              flexGrow: 1,
287→            }}
288→            onPress={onJump}
289→            isDisabled={!selectedBankId || !country}
290→          >
291→            <Trans>Link bank in browser</Trans> &rarr;
292→          </Button>
293→        </View>
294→      </View>
295→    );
296→  };
297→
298→  return (
299→    <Modal
300→      name="enablebanking-external-msg"
301→      containerProps={{ style: { width: 'clamp(400px, 30vw, 600px)' } }}
302→    >
303→      {({ state: { close } }) => (
304→        <>
305→          <ModalHeader
306→            title={
307→              reauth
308→                ? t('Re-authorize Bank (Enable Banking)')
309→                : t('Link Your Bank (Enable Banking)')
310→            }
311→            rightContent={<ModalCloseButton onPress={close} />}
312→          />
313→          <View>
314→            <Paragraph style={{ fontSize: 15 }}>
315→              {reauth ? (
316→                <Trans>
317→                  To re-authorize your bank connection, you will be redirected
318→                  to a new page where your bank will ask you to authorize access
319→                  again. Your existing accounts and transaction history will not
320→                  be affected.
321→                </Trans>
322→              ) : (
323→                <Trans>
324→                  To link your bank account, you will be redirected to a new
325→                  page where your bank will ask you to authorize access. Enable
326→                  Banking will not be able to withdraw funds from your accounts.
327→                </Trans>
328→              )}
329→            </Paragraph>
330→
331→            {error && (
332→              <>
333→                {renderError(error, t)}
334→                {reauth && (
335→                  <View style={{ alignItems: 'center', marginTop: 10 }}>
336→                    <Button variant="primary" onPress={onJump}>
337→                      <Trans>Try again</Trans>
338→                    </Button>
339→                  </View>
340→                )}
341→              </>
342→            )}
343→
344→            {!error &&
345→              (waiting || isConfigurationLoading ? (
346→                <View style={{ alignItems: 'center', marginTop: 15 }}>
347→                  <AnimatedLoading
348→                    color={theme.pageTextDark}
349→                    style={{ width: 20, height: 20 }}
350→                  />
351→                  <View style={{ marginTop: 10, color: theme.pageText }}>
352→                    {isConfigurationLoading
353→                      ? t('Checking Enable Banking configuration...')
354→                      : waiting === 'browser'
355→                        ? t('Waiting for bank authorization...')
356→                        : null}
357→                  </View>
358→
359→                  {waiting === 'browser' && (
360→                    <Link
361→                      variant="text"
362→                      onClick={onJump}
363→                      style={{ marginTop: 10 }}
364→                    >
365→                      (
366→                      <Trans>
367→                        Bank authorization not opening in a new tab? Click here
368→                      </Trans>
369→                      )
370→                    </Link>
371→                  )}
372→                </View>
373→              ) : success ? (
374→                <Paragraph
375→                  style={{ marginTop: 10, color: theme.noticeTextLight }}
376→                >
377→                  {reauth ? (
378→                    <Trans>
379→                      Success! Your bank connection has been re-authorized.
380→                      Syncing fresh transactions now. Please close this window.
381→                    </Trans>
382→                  ) : (
383→                    <Trans>
384→                      Success! Your bank accounts are being linked. Please close
385→                      this window.
386→                    </Trans>
387→                  )}
388→                </Paragraph>
389→              ) : isConfigured ? (
390→                renderLinkButton()
391→              ) : (
392→                <>
393→                  <Paragraph style={{ color: theme.errorText }}>
394→                    <Trans>
395→                      Enable Banking integration has not yet been configured.
396→                      Please contact your server administrator to set up the
397→                      Enable Banking API credentials.
398→                    </Trans>
399→                  </Paragraph>
400→                </>
401→              ))}
402→          </View>
403→        </>
404→      )}
405→    </Modal>
406→  );
407→}
