 1→import { send, sendCatch } from 'loot-core/platform/client/connection';
 2→import type { SyncServerEnableBankingAccount } from 'loot-core/types/models';
 3→
 4→// Timeout after 5 minutes of waiting for OAuth completion
 5→const OAUTH_TIMEOUT_MS = 5 * 60 * 1000;
 6→// Poll every 3 seconds
 7→const POLL_INTERVAL_MS = 3000;
 8→
 9→/**
10→ * Opens the Enable Banking OAuth flow for the given bank (ASPSP).
11→ * Returns the list of accounts and session state once the user completes
12→ * authorization in the browser.
13→ *
14→ * Flow:
15→ * 1. Calls enablebanking-create-auth IPC to get { url, state }
16→ * 2. Opens the OAuth URL in the system browser
17→ * 3. Polls enablebanking-poll-session every 3s until accounts are returned
18→ * 4. Resolves with { accounts, state } or rejects on timeout
19→ */
20→export async function authorizeEnableBank(
21→  aspspName: string,
22→  aspspCountry: string,
23→): Promise<{ accounts: SyncServerEnableBankingAccount[]; state: string }> {
24→  // Step 1: Create auth session and get the redirect URL
25→  const authResult = await send('enablebanking-create-auth', {
26→    aspspName,
27→    aspspCountry,
28→  });
29→
30→  if (!authResult || authResult.error) {
31→    throw new Error(
32→      authResult?.error ?? 'Failed to create Enable Banking auth session',
33→    );
34→  }
35→
36→  const { url, state } = authResult as { url: string; state: string };
37→
38→  // Step 2: Open the OAuth URL in the browser
39→  if (window.Actual?.openURLInBrowser) {
40→    window.Actual.openURLInBrowser(url);
41→  } else {
42→    window.open(url, '_blank');
43→  }
44→
45→  // Step 3: Poll until accounts appear or timeout
46→  return new Promise((resolve, reject) => {
47→    const startTime = Date.now();
48→
49→    const pollTimer = setInterval(async () => {
50→      if (Date.now() - startTime > OAUTH_TIMEOUT_MS) {
51→        clearInterval(pollTimer);
52→        reject(new Error('timeout'));
53→        return;
54→      }
55→
56→      const { data, error } = await sendCatch('enablebanking-poll-session', {
57→        state,
58→      });
59→
60→      if (error) {
61→        // Non-fatal - session may not be ready yet
62→        return;
63→      }
64→
65→      if (data && Array.isArray(data.accounts) && data.accounts.length > 0) {
66→        clearInterval(pollTimer);
67→        resolve({ accounts: data.accounts, state });
68→      }
69→    }, POLL_INTERVAL_MS);
70→  });
71→}
