 50→function NarrowNotSupported({
 51→  redirectTo = '/budget',
 52→  children,
 53→}: {
 54→  redirectTo?: string;
 55→  children: ReactElement;
 56→}) {
 57→  const { isNarrowWidth } = useResponsive();
 58→  const navigate = useNavigate();
 59→  useEffect(() => {
 60→    if (isNarrowWidth) {
 61→      navigate(redirectTo);
 62→    }
 63→  }, [isNarrowWidth, navigate, redirectTo]);
 64→  return isNarrowWidth ? null : children;
 65→}
 66→
 67→function WideNotSupported({
 68→  children,
 69→  redirectTo = '/budget',
 70→}: {
 71→  redirectTo?: string;
 72→  children: ReactElement;
 73→}) {
 74→  const { isNarrowWidth } = useResponsive();
 75→  const navigate = useNavigate();
 76→  useEffect(() => {
 77→    if (!isNarrowWidth) {
 78→      navigate(redirectTo);
 79→    }
 80→  }, [isNarrowWidth, navigate, redirectTo]);
 81→  return isNarrowWidth ? children : null;
 82→}
