 98→  const dispatch = useDispatch();
 99→  const { t } = useTranslation();
100→
101→  // TODO: Replace with `useAccounts` hook once it's updated to return the useQuery results.
102→  const { data: accounts, isFetching: isAccountsFetching } = useQuery(
103→    accountQueries.list(),
104→  );
105→
106→  const versionInfo = useSelector(state => state.app.versionInfo);
107→  const [notifyWhenUpdateIsAvailable] = useGlobalPref(
108→    'notifyWhenUpdateIsAvailable',
109→  );
110→  const [lastUsedVersion, setLastUsedVersion] = useLocalPref(
111→    'flags.updateNotificationShownForVersion',
112→  );
113→  const [staleThresholdHours] = useLocalPref('bankSyncStaleThresholdHours');
114→
115→  const multiuserEnabled = useMultiuserEnabled();
116→
117→  // Mutex for background bank sync triggered by visibility/focus changes.
118→  // useRef persists across re-renders and effect re-creations (the effect
119→  // depends on staleThresholdHours, so a closure-scoped let would reset to
120→  // false whenever the pref changes, allowing concurrent syncs).
121→  const isSyncingRef = useRef(false);
122→
123→  const init = useEffectEvent(() => {
124→    // Wait a little bit to make sure the sync button will get the
125→    // sync start event. This can be improved later.
126→    setTimeout(async () => {
127→      await dispatch(sync());
128→
129→      // After CRDT sync completes, trigger background bank sync for accounts
130→      // whose last sync is older than the configurable stale threshold.
131→      // CRDT sync must finish first to avoid SQLite race conditions.
132→      try {
133→        const allAccounts = await send('accounts-get');
134→        const linkedAccounts = (allAccounts || []).filter(
135→          a => a.account_sync_source && a.account_id,
136→        );
137→        const effectiveThreshold = (staleThresholdHours ?? 6) * 60 * 60 * 1000;
138→        const now = Date.now();
139→
140→        // Fetch consent status in one call to filter out expired-consent
141→        // accounts before syncing (avoids wasted Enable Banking API calls).
142→        const linkedIds = linkedAccounts.map(a => a.id);
143→        // CRITICAL: send() returns { statuses } directly. post() already
144→        // unwraps responseData.data, so there is NO extra .data layer.
145→        const syncStatuses =
146→          linkedIds.length > 0
147→            ? ((
148→                await send('enablebanking-sync-status', {
149→                  accountIds: linkedIds,
150→                })
151→              )?.statuses ?? {})
152→            : {};
153→
154→        const staleIds = linkedAccounts
155→          .filter(a => {
156→            const ebStatus = syncStatuses[a.id];
157→            // Skip EB accounts with expired consent
158→            if (
159→              ebStatus?.consent_valid_until &&
160→              new Date(ebStatus.consent_valid_until) <= new Date()
161→            ) {
162→              return false;
163→            }
164→            const lastSync = a.last_sync ? parseInt(a.last_sync, 10) : 0;
165→            return now - lastSync > effectiveThreshold;
166→          })
167→          .map(a => a.id);
168→
169→        if (staleIds.length > 0) {
170→          send('accounts-bank-sync', { ids: staleIds }).catch(() => {
171→            dispatch(
172→              addNotification({
173→                notification: {
174→                  id: 'sync-on-open-failed',
175→                  type: 'warning',
176→                  message: t('Background sync failed - check your connection'),
177→                },
178→              }),
179→            );
180→          });
181→        }
182→      } catch {
183→        // Non-blocking: don't surface errors from the sync-on-open check
184→      }
185→    }, 100);
186→
187→    async function run() {
188→      await global.Actual.waitForUpdateReadyForDownload(); // This will only resolve when an update is ready
189→      dispatch(
190→        addNotification({
191→          notification: {
192→            type: 'message',
193→            title: t('A new version of Actual is available!'),
194→            message: t(
195→              'Click the button below to reload and apply the update.',
196→            ),
197→            sticky: true,
198→            id: 'update-reload-notification',
199→            button: {
200→              title: t('Update now'),
201→              action: async () => {
202→                await global.Actual.applyAppUpdate();
203→              },
204→            },
205→          },
206→        }),
207→      );
208→    }
209→
210→    run();
211→  });
212→
213→  useEffect(() => init(), []);
214→
215→  // Bank sync check on visibility/focus changes. Lives in FinancesApp (not
216→  // App.tsx) because useLocalPref requires budget context - App.tsx renders
217→  // before any budget is loaded, so useLocalPref there produces the wrong
218→  // localStorage key ('undefined-bankSyncStaleThresholdHours').
219→  useEffect(() => {
220→    async function onVisibilityOrFocus() {
221→      // App.tsx already fires dispatch(sync()) (CRDT sync) on visibilitychange.
222→      // The two handlers run concurrently - this is acceptable because bank
223→      // sync reads from the EB API (not local DB) and is idempotent.
224→      if (document.hidden || isSyncingRef.current) return;
225→      isSyncingRef.current = true;
226→      try {
227→        const allAccounts = await send('accounts-get');
228→        const linkedAccounts = (allAccounts || []).filter(
229→          a => a.account_sync_source && a.account_id,
230→        );
231→        const effectiveThreshold = (staleThresholdHours ?? 6) * 60 * 60 * 1000;
232→        const now = Date.now();
233→
234→        const linkedIds = linkedAccounts.map(a => a.id);
235→        const syncStatuses =
236→          linkedIds.length > 0
237→            ? ((
238→                await send('enablebanking-sync-status', {
239→                  accountIds: linkedIds,
240→                })
241→              )?.statuses ?? {})
242→            : {};
243→
244→        const staleIds = linkedAccounts
245→          .filter(a => {
246→            const ebStatus = syncStatuses[a.id];
247→            if (
248→              ebStatus?.consent_valid_until &&
249→              new Date(ebStatus.consent_valid_until) <= new Date()
250→            ) {
251→              return false;
252→            }
253→            const lastSync = a.last_sync ? parseInt(a.last_sync, 10) : 0;
254→            return now - lastSync > effectiveThreshold;
255→          })
256→          .map(a => a.id);
257→
258→        if (staleIds.length > 0) {
