307→                },
308→              },
309→              onClose: () => {
310→                setLastUsedVersion(versionInfo.latestVersion);
311→              },
312→            },
313→          }),
314→        );
315→      }
316→    }
317→  }, [
318→    dispatch,
319→    lastUsedVersion,
320→    notifyWhenUpdateIsAvailable,
321→    setLastUsedVersion,
322→    t,
323→    versionInfo,
324→  ]);
325→
326→  useConsentExpiryNotifications();
327→  useBankSyncNotification();
