 42→function useAvailableBanks(country: string) {
 43→  const [banks, setBanks] = useState<AspspOption[]>([]);
 44→  const [isLoading, setIsLoading] = useState(false);
 45→  const [isError, setIsError] = useState(false);
 46→
 47→  useEffect(() => {
 48→    async function fetch() {
 49→      setIsError(false);
 50→
 51→      if (!country) {
 52→        setBanks([]);
 53→        setIsLoading(false);
 54→        return;
 55→      }
 56→
 57→      setIsLoading(true);
 58→
 59→      const { data, error } = await sendCatch('enablebanking-get-banks', {
 60→        country,
 61→      });
 62→
 63→      if (error || !Array.isArray(data)) {
 64→        setIsError(true);
 65→        setBanks([]);
 66→      } else {
 67→        // Enable Banking ASPSPs have a `name` field; map to autocomplete format
 68→        const options: AspspOption[] = data.map(
 69→          (aspsp: { name: string; country?: string }) => ({
 70→            id: aspsp.name,
 71→            name: aspsp.name,
 72→          }),
 73→        );
 74→        setBanks(options);
 75→      }
 76→
 77→      setIsLoading(false);
 78→    }
 79→
 80→    fetch();
 81→  }, [country]);
 82→
 83→  return {
 84→    data: banks,
 85→    isLoading,
 86→    isError,
 87→  };
 88→}
