 92→  t: ReturnType<typeof useTranslation>['t'],
 93→) {
 94→  return (
 95→    <Error style={{ alignSelf: 'center', marginBottom: 10 }}>
 96→      {error.code === 'timeout'
 97→        ? t('Timed out. Please try again.')
 98→        : t(
 99→            'An error occurred while linking your account, sorry! The potential issue could be: {{ message }}',
100→            { message: error.message },
101→          )}
102→    </Error>
103→  );
104→}
