const appData = process.env.APPDATA || 'C:/Users/Eagi/AppData/Roaming';
const fnmBase = path.join(appData, 'fnm', 'node-versions');
console.log('fnm base:', fnmBase);

// Check common yarn locations
const candidates = [
  path.join(nodeDir, 'yarn.cmd'),
  path.join(nodeDir, 'yarn'),
  path.join(appData, 'npm', 'yarn.cmd'),
  path.join(appData, 'npm', 'yarn'),
  'C:/Users/Eagi/bin/yarn',
  'C:/Program Files/nodejs/yarn.cmd',
];

for (const c of candidates) {
  try {
    if (fs.existsSync(c)) {
      console.log('FOUND:', c);
    }
  } catch (e) {}
}

// Also check if corepack is available
try {
  const result = execFileSync('cmd.exe', ['/c', 'where corepack'], { encoding: 'utf8' });
  console.log('corepack:', result.trim());
} catch (e) {
  console.log('corepack not found');
}

// Check npm global prefix
try {
  const result = execFileSync('cmd.exe', ['/c', 'npm prefix -g'], { encoding: 'utf8', env: process.env });
  console.log('npm global prefix:', result.trim());
} catch (e) {
  console.log('npm prefix error:', e.message);
